public enum RazerProto
{
    /// <summary>Älteres "Standard Matrix"-Protokoll</summary>
    Std,
    /// <summary>Neueres "Extended Matrix"-Protokoll</summary>
    Ext,
    /// <summary>Eine LED-Reihe (ältere Mäuse/Zubehör)</summary>
    Linear,
    /// <summary>Chroma ARGB-Controller (Lüfter/LED-Streifen)</summary>
    Argb,
    /// <summary>Kraken 7.1 / V2 / Ultimate (Speicheradressen-Protokoll)</summary>
    Kraken1,
    /// <summary>Kraken V3 / V3 X / HyperSense / Kitty V2 Pro</summary>
    Kraken3,
    /// <summary>Kraken V4 / Kitty V3 Pro</summary>
    Kraken4
}

